     1→import { describe, it, expect } from "vitest";
     2→import {
     3→  compilePattern,
     4→  matchUrl,
     5→  buildUrl,
     6→  type RouteEntry,
     7→} from "./route-compiler";
     8→
     9→// ─── compilePattern ──────────────────────────────────────────────────────────
    10→
    11→describe("compilePattern", () => {
    12→  it("compiles constant-only pattern", () => {
    13→    const compiled = compilePattern("/documents");
    14→    expect(compiled.regex.test("/documents")).toBe(true);
    15→    expect(compiled.regex.test("/documents/extra")).toBe(false);
    16→    expect(compiled.paramNames).toEqual([]);
    17→    expect(compiled.restParam).toBeNull();
    18→  });
    19→
    20→  it("compiles single param pattern", () => {
    21→    const compiled = compilePattern("/workspace/:workspaceId");
    22→    expect(compiled.regex.test("/workspace/my-proj")).toBe(true);
    23→    expect(compiled.regex.test("/workspace/my-proj/extra")).toBe(false);
    24→    expect(compiled.paramNames).toEqual(["workspaceId"]);
    25→    expect(compiled.restParam).toBeNull();
    26→  });
    27→
    28→  it("compiles rest param pattern", () => {
    29→    const compiled = compilePattern("/workspace/:workspaceId/pages/:pageSlug+");
    30→    expect(compiled.regex.test("/workspace/x/pages/a/b/c")).toBe(true);
    31→    expect(compiled.regex.test("/workspace/x/pages/")).toBe(false);
    32→    expect(compiled.regex.test("/workspace/x/pages")).toBe(false);
    33→    expect(compiled.paramNames).toEqual(["workspaceId", "pageSlug"]);
    34→    expect(compiled.restParam).toBe("pageSlug");
    35→  });
    36→
    37→  it("uses ^ and $ anchoring", () => {
    38→    const compiled = compilePattern("/settings/:section");
    39→    expect(compiled.regex.test("/settings/general")).toBe(true);
    40→    expect(compiled.regex.test("/settings/general/extra")).toBe(false);
    41→    expect(compiled.regex.test("prefix/settings/general")).toBe(false);
    42→  });
    43→});
    44→
    45→// ─── Test Data ───────────────────────────────────────────────────────────────
    46→
    47→const TEST_ENTRIES: RouteEntry[] = [
    48→  {
    49→    pattern: "/documents",
    50→    icon: { type: "lucide", value: "file-text" },
    51→    title: "Documents",
    52→  },
    53→  {
    54→    pattern: "/workspace",
    55→    icon: { type: "lucide", value: "home" },
    56→    title: "Workspaces",
    57→  },
    58→  {
    59→    pattern: "/workspace/:workspaceId",
    60→    icon: { type: "lucide", value: "home" },
    61→    title: (p) => p.workspaceId,
    62→  },
    63→  {
    64→    pattern: "/workspace/:workspaceId/pages",
    65→    icon: { type: "lucide", value: "layout-grid" },
    66→    title: "Pages",
    67→  },
    68→  {
    69→    pattern: "/workspace/:workspaceId/pages/:pageSlug+",
    70→    icon: { type: "lucide", value: "file-text" },
    71→    title: (p) => p.pageSlug.split("/").pop()!,
    72→  },
    73→  {
    74→    pattern: "/workspace/:workspaceId/web",
    75→    icon: { type: "lucide", value: "globe" },
    76→    title: (p) => p.title ?? "Web",
    77→    queryParams: ["url", "title"],
    78→  },
    79→  {
    80→    pattern: "/settings",
    81→    icon: { type: "lucide", value: "settings" },
    82→    title: "Settings",
    83→    isContainer: true,
    84→  },
    85→  {
    86→    pattern: "/settings/:section",
    87→    icon: { type: "lucide", value: "settings" },
    88→    title: (p) => p.section,
    89→  },
    90→];
    91→
    92→// ─── matchUrl ────────────────────────────────────────────────────────────────
    93→
    94→describe("matchUrl", () => {
    95→  it("matches exact path", () => {
    96→    const match = matchUrl("/documents", TEST_ENTRIES);
    97→    expect(match).not.toBeNull();
    98→    expect(match!.pattern).toBe("/documents");
    99→    expect(match!.params).toEqual({});
   100→  });
   101→
   102→  it("matches parameterized path", () => {
   103→    const match = matchUrl("/workspace/my-proj", TEST_ENTRIES);
   104→    expect(match!.pattern).toBe("/workspace/:workspaceId");
   105→    expect(match!.params).toEqual({ workspaceId: "my-proj" });
   106→  });
   107→
   108→  it("matches rest param path", () => {
   109→    const match = matchUrl("/workspace/x/pages/a/b/c", TEST_ENTRIES);
   110→    expect(match!.pattern).toBe("/workspace/:workspaceId/pages/:pageSlug+");
   111→    expect(match!.params).toEqual({ workspaceId: "x", pageSlug: "a/b/c" });
   112→  });
   113→
   114→  it("extracts declared query params", () => {
   115→    const match = matchUrl(
   116→      "/workspace/x/web?url=https%3A%2F%2Fexample.com&title=Test&extra=ignored",
   117→      TEST_ENTRIES,
   118→    );
   119→    expect(match!.params).toEqual({
   120→      workspaceId: "x",
   121→      url: "https://example.com",
   122→      title: "Test",
   123→    });
   124→  });
   125→
   126→  it("prefers more specific route (no splat over splat)", () => {
   127→    const match = matchUrl("/workspace/x/pages", TEST_ENTRIES);
   128→    expect(match!.pattern).toBe("/workspace/:workspaceId/pages");
   129→  });
   130→
   131→  it("returns null for unknown URL", () => {
   132→    expect(matchUrl("/unknown/path", TEST_ENTRIES)).toBeNull();
   133→  });
   134→});
   135→
   136→// ─── buildUrl ────────────────────────────────────────────────────────────────
   137→
   138→describe("buildUrl", () => {
   139→  it("builds constant-only URL", () => {
   140→    expect(buildUrl("/documents", {}, TEST_ENTRIES)).toBe("/documents");
   141→  });
   142→
   143→  it("builds parameterized URL", () => {
   144→    expect(
   145→      buildUrl("/workspace/:workspaceId", { workspaceId: "my-proj" }, TEST_ENTRIES),
   146→    ).toBe("/workspace/my-proj");
   147→  });
   148→
   149→  it("builds rest param URL", () => {
   150→    expect(
   151→      buildUrl(
   152→        "/workspace/:workspaceId/pages/:pageSlug+",
   153→        { workspaceId: "x", pageSlug: "a/b" },
   154→        TEST_ENTRIES,
   155→      ),
   156→    ).toBe("/workspace/x/pages/a/b");
   157→  });
   158→
   159→  it("appends declared query params in order", () => {
   160→    expect(
   161→      buildUrl(
   162→        "/workspace/:workspaceId/web",
   163→        { workspaceId: "x", url: "https://a.com", title: "T" },
   164→        TEST_ENTRIES,
   165→      ),
   166→    ).toBe("/workspace/x/web?url=https%3A%2F%2Fa.com&title=T");
   167→  });
   168→
   169→  it("throws on empty rest param", () => {
   170→    expect(() =>
   171→      buildUrl(
   172→        "/workspace/:workspaceId/pages/:pageSlug+",
   173→        { workspaceId: "x", pageSlug: "" },
   174→        TEST_ENTRIES,
   175→      ),
   176→    ).toThrow();
   177→  });
   178→
   179→  it("round-trips with matchUrl", () => {
   180→    const url1 = buildUrl(
   181→      "/workspace/:workspaceId/pages/:pageSlug+",
   182→      { workspaceId: "x", pageSlug: "a/b" },
   183→      TEST_ENTRIES,
   184→    );
   185→    const match = matchUrl(url1, TEST_ENTRIES)!;
   186→    const url2 = buildUrl(match.pattern, match.params, TEST_ENTRIES);
   187→    expect(url1).toBe(url2);
   188→  });
   189→});
